let batchData=[];const beforeWarehouseRender=render;document.querySelector('.more-nav').insertAdjacentHTML('beforeend','<a href="#warehouse">Мои запасы</a>');
async function loadBatches(){if(!account)return;try{batchData=(await api('batches')).batches;render()}catch(e){toast(e.message)}}
function warehousePage(){return heading('Свой урожай под учётом.','Партии, резерв, выдача и история движения.','<button class="btn" onclick="newBatch()">＋ Записать сбор</button>')+`<p class="note">Это учёт запасов. Физическое хранение и доставка согласуются с фермой отдельно. Самостоятельные записи не считаются подтверждённой приёмкой.</p><div class="grid">${batchData.length?batchData.map(b=>`<article class="panel"><span class="pill">Грядка №${b.plot_id} · ${b.verified?'Принято':'Нужна приёмка'}</span><h3>${esc(b.crop)}</h3><p>Сбор: ${String(b.harvested_on).slice(0,10)}</p><div class="metrics"><span>Остаток: ${b.balance_grams/1000} кг</span><span>Резерв: ${b.reserved_grams/1000} кг</span><span>Доступно: ${(b.balance_grams-b.reserved_grams)/1000} кг</span></div><div class="actions"><button class="btn" onclick="showPassport('${b.id}')">Паспорт партии</button><button class="btn light" onclick="stockMove('${b.id}')">Движение</button></div></article>`).join(''):'<section class="panel empty"><h3>Урожай появится после сбора</h3><p>Запиши фактическую массу и грядку происхождения.</p></section>'}</div>`}
function newBatch(){if(!account){profile();return}formAsync('Фактический сбор урожая',`<label>Культура<input name="crop" required maxlength="100"></label><label>Грядка<select name="plot" required>${plotOptions()}</select></label><label>Дата сбора<input type="date" name="date" required></label><label>Масса, кг<input name="kg" type="number" min="0.001" max="100000" step="0.001" required></label><button class="btn">Записать сбор</button>`,async f=>{await api('batch-create',{plot:Number(f.get('plot')),crop:f.get('crop'),date:f.get('date'),grams:Math.round(Number(f.get('kg'))*1000)});await loadBatches()})}
function stockMove(id){if(!['admin','farmer'].includes(account?.role)){formAsync('🧺 Куда отправить урожай?','<p>Соберите корзину домой, подарите её или разместите принятое на склад на маркете.</p><a class="btn" href="#lifecycle" onclick="modal.close()">Корзины, доставка и продажа</a>',async()=>{});return}const key=crypto.randomUUID();formAsync('Списание после осмотра','<label>Масса, кг<input name="kg" type="number" step="0.001" min="0.001" required></label><label>Результат осмотра<input name="reason" required minlength="10" maxlength="500"></label><p>Зарезервированный урожай списать нельзя. Сначала отмените доставку или объявление.</p><button class="btn">Подтвердить списание</button>',async f=>{await api('stock-move',{id,key,kind:'writeoff',grams:Math.round(Number(f.get('kg'))*1000),reason:f.get('reason')});await loadBatches()})}
async function showPassport(id){try{const d=await api('passport',{id});const kinds={received:'Принято на учёт',reserve:'Резерв',release:'Освобождение резерва',ship:'Выдача',writeoff:'Списание'};modalForm('Паспорт: '+esc(d.batch.crop),`<p>Грядка №${d.batch.plot_id} · сбор ${String(d.batch.harvested_on).slice(0,10)}</p><section class="quality-card"><span>🧺</span><h3>${d.rating.score===null?'Ожидает оценки':d.rating.score+' / 100'}</h3><p>${esc(d.rating.reason)}</p>${(d.assessments?.[0]?.breakdown||[]).map(c=>`<p><b>${esc(c.name)}: ${c.score}/100</b> · вес ${c.weight}%<br>${esc(c.evidence)}</p>`).join('')}<small>Методика: ${esc(d.rating.version)}. Цена семян и число нажатий не добавляют баллы.</small></section>${account.role==='admin'?`<button type="button" class="btn light" onclick="assessHarvest('${id}')">Подтвердить оценку при приёмке</button>`:''}<h3>Подтверждённые работы этого цикла</h3><p class="note">Показываются только работы, явно связанные с циклом этой партии. Старые записи без связи не подмешиваются.</p>${d.works.map(w=>`<div class="event">${esc(w.title)}<small>${fmt(w.finished_at)}</small><p>${esc(w.report||'')}</p></div>`).join('')||'<p>Подтверждённых работ нет.</p>'}<h3>Движение партии</h3>${d.events.map(e=>`<div class="event">${kinds[e.kind]} · ${e.grams/1000} кг<small>${fmt(e.created_at)}</small><p>${esc(e.reason)}</p></div>`).join('')}`,()=>{})}catch(e){toast(e.message)}}
render=function(){if(location.hash==='#warehouse'){$('#app').innerHTML=warehousePage();$('#crumb').textContent='ЗАПАСЫ'}else beforeWarehouseRender()};addEventListener('hashchange',()=>{if(location.hash==='#warehouse')loadBatches()});render();if(location.hash==='#warehouse')loadBatches();

function assessHarvest(id){formAsync('🧺 Оценка фермы по приёмке',`${[['condition','Состояние при приёмке',40],['ripeness','Согласованная спелость',25],['handling','Условия хранения',20],['traceability','Прослеживаемость',15]].map(([k,title,weight])=>`<fieldset><legend>${title} · ${weight}%</legend><label>Оценка 0–100<input name="${k}" type="number" min="0" max="100" required></label><label>Что проверено, где зафиксировано<textarea name="${k}_evidence" minlength="10" maxlength="1000" required></textarea></label></fieldset>`).join('')}<p>Используйте результаты осмотра и записи. Цена семян и количество операций не влияют на оценку. Это оценка фермы, а не лабораторное заключение.</p><button class="btn">Подтвердить оценку</button>`,async f=>{const values=Object.fromEntries(['condition','ripeness','handling','traceability'].map(k=>[k,{score:Number(f.get(k)),evidence:f.get(k+'_evidence')}]));await api('quality-assess',{id,values});toast('Оценка сохранена в истории партии')})}
